import networkx as nx
import random
import itertools

def is_girth_at_least_7(G):
    for cycle in nx.cycle_basis(G):
        if len(cycle) < 7:
            return False
    # Actually, cycle_basis doesn't find all cycles.
    # We need to check all cycles.
    # For a small graph, we can use nx.shortest_cycle.
    try:
        if nx.girth(G) < 7:
            return False
    except:
        # If no cycles, girth is infinity
        pass
    return True

def find_graph():
    # Try to build a graph with 17 vertices and 30 edges
    # Start with a random graph and remove edges to satisfy girth
    while True:
        G = nx.Graph()
        G.add_nodes_from(range(17))
        edges = list(itertools.combinations(range(17), 2))
        random.shuffle(edges)

        for u, v in edges:
            G.add_edge(u, v)
            if not is_girth_at_least_7(G):
                G.remove_edge(u, v)
            if G.number_of_edges() == 30:
                break

        if G.number_of_edges() >= 30:
            # Check if 4-colorable
            coloring = nx.coloring.greedy_color(G, strategy='largest_first')
            if max(coloring.values()) + 1 <= 4:
                return G.edges()

